package main

import (
	"bufio"
	"fmt"
	"os"
)

const MOD = 1000000007

func modAdd(a, b int) int {
	s := a + b
	if s >= MOD {
		s -= MOD
	}
	return s
}

func modSub(a, b int) int {
	s := a - b
	if s < 0 {
		s += MOD
	}
	return s
}

func modMul(a, b int) int {
	return int((int64(a) * int64(b)) % MOD)
}

func modPow(a, e int) int {
	res := 1
	base := a
	for e > 0 {
		if e&1 == 1 {
			res = modMul(res, base)
		}
		base = modMul(base, base)
		e >>= 1
	}
	return res
}

func modInv(a int) int {
	return modPow(a, MOD-2)
}

func solve() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Split(bufio.ScanWords)
	if !scanner.Scan() {
		return
	}
	n := 0
	fmt.Sscanf(scanner.Text(), "%d", &n)
	scanner.Scan()
	p := 0
	fmt.Sscanf(scanner.Text(), "%d", &p)

	// Compute S0, S1, S2 for d=1..p-1
	// g(d) = 0 for d in {1,2}
	// for d>=3: k = d/3
	// if d%3 == 0 or 2: g(d) = g(k)
	// if d%3 == 1: g(d) = 1 if g(k)==0 else 0
	// S0 = sum (p-d) for g=0
	// S1 = sum (p-d) for g=1
	// S2 = sum (p-d) for g=2

	// Memoization for (cnt0, cnt1, cnt2, sum_d) for range [L, R]
	memo := make(map[int64][4]int) // key: L<<32 | R, value: [cnt0, cnt1, cnt2, sum_d]

	var getStats func(L, R int) [4]int
	getStats = func(L, R int) [4]int {
		if L > R {
			return [4]int{0, 0, 0, 0}
		}
		key := (int64(L) << 32) | int64(R)
		if val, ok := memo[key]; ok {
			return val
		}
		var res [4]int
		if R <= 2 {
			// g(d)=0 for d=1,2
			for d := L; d <= R; d++ {
				res[0]++
				res[3] += d
			}
			memo[key] = res
			return res
		}
		if L <= 2 {
			// split
			left := getStats(L, 2)
			right := getStats(3, R)
			for i := 0; i < 4; i++ {
				res[i] = modAdd(left[i], right[i])
			}
			memo[key] = res
			return res
		}
		// L >= 3
		// For each r in {0,1,2}, find d in [L,R] with d%3 == r
		// d = 3*k + r
		// k in [k_min, k_max]
		for r := 0; r < 3; r++ {
			// smallest d >= L with d%3 == r
			d0 := L + ((r - L%3 + 3) % 3)
			if d0 > R {
				continue
			}
			// largest d <= R with d%3 == r
			d1 := R - ((R - r + 3) % 3)
			// k from k_min to k_max
			k_min := d0 / 3
			k_max := d1 / 3
			// get stats for k in [k_min, k_max]
			kStats := getStats(k_min, k_max)
			cnt_k := kStats[0] + kStats[1] + kStats[2] // total count
			if cnt_k == 0 {
				continue
			}
			sum_k := kStats[3]
			// sum of d = 3*sum_k + r*cnt_k
			sum_d := modAdd(modMul(3, sum_k), modMul(r, cnt_k))
			// cnt0, cnt1, cnt2
			var c0, c1, c2 int
			if r == 0 || r == 2 {
				// g(d) = g(k)
				c0 = kStats[0]
				c1 = kStats[1]
				c2 = kStats[2]
			} else { // r == 1
				// g(d) = 1 if g(k)==0 else 0
				// g(k) can be 0,1,2
				// if g(k)==0 -> g(d)=1
				// else -> g(d)=0
				c0 = modAdd(kStats[1], kStats[2]) // g(k)!=0
				c1 = kStats[0]                    // g(k)==0
				c2 = 0
			}
			res[0] = modAdd(res[0], c0)
			res[1] = modAdd(res[1], c1)
			res[2] = modAdd(res[2], c2)
			res[3] = modAdd(res[3], sum_d)
		}
		memo[key] = res
		return res
	}

	full := getStats(1, p-1)
	cnt0 := full[0]
	cnt1 := full[1]
	cnt2 := full[2]
	sum_d := full[3]

	S0 := modSub(modMul(p, cnt0), sum_d)
	S1 := modSub(modMul(p, cnt1), sum_d)
	S2 := modSub(modMul(p, cnt2), sum_d)

	// Total pairs = S0 + S1 + S2
	// We need number of sequences of n pairs with XOR != 0
	// Use generating functions / DP on XOR
	// XOR values: 0,1,2
	// DP: dp[x] = number of ways for current length with XOR = x
	// Start: dp[0]=1, dp[1]=0, dp[2]=0
	// Transition: new_dp[x] = sum_y dp[y] * cnt[x^y]
	// Since n <= 1000, we can do O(n * 3^2) = O(9n) = 9000 ops
	dp := [3]int{1, 0, 0}
	for i := 0; i < n; i++ {
		new_dp := [3]int{0, 0, 0}
		for x := 0; x < 3; x++ {
			if dp[x] == 0 {
				continue
			}
			// add S0 with g=0 -> XOR stays x
			new_dp[x] = modAdd(new_dp[x], modMul(dp[x], S0))
			// add S1 with g=1 -> XOR becomes x^1
			new_dp[x^1] = modAdd(new_dp[x^1], modMul(dp[x], S1))
			// add S2 with g=2 -> XOR becomes x^2
			new_dp[x^2] = modAdd(new_dp[x^2], modMul(dp[x], S2))
		}
		dp = new_dp
	}
	// Answer is dp[1] + dp[2] (XOR != 0)
	ans := modAdd(dp[1], dp[2])
	fmt.Println(ans)
}

func main() {
	solve()
}
